	if (tps != null && tps.length > 0) {
		TypeReference[] trs = new TypeReference[tps.length];
		for (int i = 0; i < tps.length; i++) {
			trs[i] = new SingleTypeReference(tps[i].name, p);
		}
		rr[idx] = trs;
		filled = true;
	}

